package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"os"
	"strings"
	"sync"
	"time"
)

const (
	maxRetries    = 3
	rateLimitRPS  = 10
	allowedScheme = "https"
)

var (
	hmacSecret []byte

	allowedHosts = map[string]bool{
		"api.internal.corp":   true,
		"cdn.internal.corp":   true,
		"hooks.internal.corp": true,
	}

	httpClient = &http.Client{
		Timeout: 10 * time.Second,
	}
)

type RateLimiter struct {
	mu       sync.Mutex
	tokens   float64
	lastTime time.Time
	rate     float64
}

func NewRateLimiter(rps float64) *RateLimiter {
	return &RateLimiter{tokens: rps, lastTime: time.Now(), rate: rps}
}

func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	elapsed := now.Sub(rl.lastTime).Seconds()
	rl.tokens += elapsed * rl.rate
	if rl.tokens > rl.rate {
		rl.tokens = rl.rate
	}
	rl.lastTime = now
	if rl.tokens >= 1 {
		rl.tokens--
		return true
	}
	return false
}

type WebhookJob struct {
	ID          string
	CallbackURL string
	Payload     string
	Signature   string
	RetryCount  int
}

func computeSignature(jobID, callbackURL string) string {
	mac := hmac.New(sha256.New, hmacSecret)
	mac.Write([]byte(jobID + "|" + callbackURL))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifySignature(job WebhookJob) bool {
	expected := computeSignature(job.ID, job.CallbackURL)
	return hmac.Equal([]byte(expected), []byte(job.Signature))
}

func validateAndCanonicalizeURL(rawURL string) (string, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return "", fmt.Errorf("invalid URL: %w", err)
	}
	if parsed.Scheme != allowedScheme {
		return "", fmt.Errorf("scheme %q not allowed", parsed.Scheme)
	}
	// Extract hostname without port for validation
	host := parsed.Hostname()
	if !allowedHosts[host] {
		return "", fmt.Errorf("host %q not in allowlist", host)
	}
	// Rebuild canonical URL from validated components only
	canonical := &url.URL{
		Scheme: parsed.Scheme,
		Host:   parsed.Host,
		Path:   parsed.Path,
	}
	return canonical.String(), nil
}

func executeWebhook(job WebhookJob, limiter *RateLimiter) error {
	if !verifySignature(job) {
		return fmt.Errorf("invalid signature for job %s", job.ID)
	}
	finalURL, err := validateAndCanonicalizeURL(job.CallbackURL)
	if err != nil {
		return fmt.Errorf("URL validation failed: %w", err)
	}
	for attempt := 0; attempt <= maxRetries; attempt++ {
		if !limiter.Allow() {
			time.Sleep(100 * time.Millisecond)
			continue
		}
		log.Printf("[attempt %d] Dispatching job %s to %s", attempt, job.ID, finalURL)
		resp, err := httpClient.Post(finalURL, "application/json", strings.NewReader(job.Payload))
		if err != nil {
			log.Printf("Request failed: %v", err)
			time.Sleep(time.Duration(attempt+1) * time.Second)
			continue
		}
		resp.Body.Close()
		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
			log.Printf("Job %s completed successfully", job.ID)
			return nil
		}
		if resp.StatusCode >= 500 {
			time.Sleep(time.Duration(attempt+1) * time.Second)
			continue
		}
		return fmt.Errorf("non-retryable status: %d", resp.StatusCode)
	}
	return fmt.Errorf("job %s exhausted retries", job.ID)
}

func enqueueHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	callbackURL := r.FormValue("callback_url")
	payload := r.FormValue("payload")
	jobID := fmt.Sprintf("job-%d", time.Now().UnixNano())
	sig := computeSignature(jobID, callbackURL)
	job := WebhookJob{
		ID:          jobID,
		CallbackURL: callbackURL,
		Payload:     payload,
		Signature:   sig,
		RetryCount:  0,
	}
	limiter := NewRateLimiter(rateLimitRPS)
	go func() {
		if err := executeWebhook(job, limiter); err != nil {
			log.Printf("Job %s failed: %v", job.ID, err)
		}
	}()
	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "{\"job_id\": %q}", jobID)
}

func main() {
	secret := os.Getenv("WEBHOOK_HMAC_SECRET")
	if secret == "" {
		log.Fatal("WEBHOOK_HMAC_SECRET environment variable must be set")
	}
	hmacSecret = []byte(secret)

	mux := http.NewServeMux()
	mux.HandleFunc("/enqueue", enqueueHandler)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	log.Println("Worker listening on :8080")
	log.Fatal(srv.ListenAndServe())
}
